import itertools

def solve_small(n):
    max_s = 0
    # We need to iterate over all graphs with n vertices.
    # However, that's 2^(n(n-1)/2) graphs. For n=5, it's 2^10 = 1024. For n=6, it's 2^15 = 32768.
    # Let's do n=5, 6, 7.

    for num_edges in range(n * (n - 1) // 2 + 1):
        for edges in itertools.combinations(itertools.combinations(range(n), 2), num_edges):
            # edges is a tuple of pairs
            adj = [set() for _ in range(n)]
            edge_set = set()
            for u, v in edges:
                adj[u].add(v)
                adj[v].add(u)
                edge_set.add(tuple(sorted((u, v))))

            s_count = 0
            for u, v in itertools.combinations(range(n), 2):
                if tuple(sorted((u, v))) not in edge_set:
                    # Check if they have a common neighbor
                    if any(w in adj[u] and w in adj[v] for w in range(n)):
                        s_count += 1
            if s_count > max_s:
                max_s = s_count
    return max_s

for n in range(3, 8):
    print(f"n={n}, max_s={solve_small(n)}")
